def clean(df):
    df = df.copy()
    df['species'] = df['species'].str.strip()
    df['species'] = df['species'].replace({'adelie': 'Adelie', 'Adeile': 'Adelie', 'Gentto': 'Gentoo', 'Chinstarp': 'Chinstrap'})
    return df

def answer(df):
    df = clean(df)
    sub = df[df['species'] == 'Adelie']
    return sub.groupby('island')['bill_length_mm'].mean().to_dict()
